	m.ID = types.StringValue(firstNonEmptyStr(getString(obj, "Guid"), getString(obj, "Id"), getString(obj, "Identity")))
	m.AggregationTimeWindowForDlpAlerts = types.StringValue(getString(obj, "AggregationTimeWindowForDlpAlerts"))
